// ─────────────────────────────────────────────────────────────────────────────
// `second` — second element of a list.
//
// Scheme semantics: (second list) → the element at index 1 of a non-empty list.
// ─────────────────────────────────────────────────────────────────────────────

declare function second<T>(xs: List<T>): T;
